import{_ as t,o,c as a,a3 as r}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Short Links — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Short Links — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/short-links"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Short Links — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/short-links"}]]},"headers":[],"relativePath":"user-guide/short-links.md","filePath":"user-guide/short-links.md","lastUpdated":1794259478000}'),s={name:"user-guide/short-links.md"};function i(n,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="short-links-—-user-guide" tabindex="-1">Short Links — User Guide <a class="header-anchor" href="#short-links-—-user-guide" aria-label="Permalink to &quot;Short Links — User Guide&quot;">​</a></h1><h2 id="install-the-module" tabindex="-1">Install the module <a class="header-anchor" href="#install-the-module" aria-label="Permalink to &quot;Install the module&quot;">​</a></h2><p><strong>Short Links</strong> is a free Marketplace module. Install it from <strong>Marketplace → Operations</strong> before creating links.</p><h2 id="who-can-use-short-links" tabindex="-1">Who can use Short Links <a class="header-anchor" href="#who-can-use-short-links" aria-label="Permalink to &quot;Who can use Short Links&quot;">​</a></h2><p>Your workspace must have the <strong>Short Links</strong> module installed. Your role needs the relevant permissions:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Allows</th></tr></thead><tbody><tr><td><code>view</code></td><td>List and open short links</td></tr><tr><td><code>create</code></td><td>Create new links</td></tr><tr><td><code>update</code></td><td>Edit links</td></tr><tr><td><code>delete</code> / <code>restore</code> / <code>force.delete</code></td><td>Trash lifecycle</td></tr><tr><td><code>view_analytics</code></td><td>Click stats on the record page</td></tr></tbody></table><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><p>Open <strong>Short Links</strong> from the sidebar (Operations).</p><ul><li>Search by title or destination URL</li><li>Filter by status (Active / Paused), type (Redirect / Splash / Bio), and trash state when you can restore</li><li>KPI cards show total links, active links, total clicks, and clicks in the last 7 days</li><li><strong>Type</strong> and <strong>Short URL</strong> columns show experience type and a copyable short URL; you can also copy from the row menu</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New short link</strong> (shortcut: <code>n</code> when the list is focused and you have create permission)</li><li>Enter a destination URL (required) and optional title, status, expiry, and UTM parameters</li><li>Choose a <strong>Type</strong>: Redirect (immediate), Splash page (branded interstitial then continue), or Bio / link page (multiple outbound buttons)</li><li>For splash pages, set headline, body, CTA label, optional delay, and theme. For bio pages, add links as <code>Label | URL</code> lines.</li><li>Optionally set a <strong>Custom slug</strong> (e.g. <code>launch-2026</code>) for a vanity URL — leave blank for an auto-generated 7-character code. Slugs cannot be changed after creation.</li><li>Save — EloSync generates a public short URL on <code>https://go.elosync.com/r/{code}</code>. Your operator may use a different short domain via <code>SHORT_LINK_BASE_URL</code>.</li></ol><p>Edit from the row menu or the record page. Focus search with <code>Ctrl/⌘+F</code>.</p><h2 id="record-page" tabindex="-1">Record page <a class="header-anchor" href="#record-page" aria-label="Permalink to &quot;Record page&quot;">​</a></h2><ul><li><strong>Details</strong> — type, slug, destination, status, campaign/tags, starts/expiry, copyable short URL</li><li><strong>Splash page</strong> / <strong>Bio links</strong> — experience-specific fields when the link is not a plain redirect</li><li><strong>Analytics</strong> (requires <code>view_analytics</code>) — total and unique clicks, optional date range, clicks-by-day and by-hour charts, top referrers, devices, browsers, operating systems, countries, and CSV export</li><li><strong>Download QR</strong> — SVG QR code for the short URL</li><li>Optional <strong>starts at</strong>, <strong>max clicks</strong>, <strong>password</strong>, <strong>campaign</strong>, and <strong>tags</strong> for marketing controls</li></ul><h2 id="custom-short-domain" tabindex="-1">Custom short domain <a class="header-anchor" href="#custom-short-domain" aria-label="Permalink to &quot;Custom short domain&quot;">​</a></h2><p>On the Short Links list page, workspaces with update permission can propose a custom hostname (for example <code>links.yourcompany.com</code>):</p><ol><li>Enter the hostname and save</li><li>Add the shown DNS <strong>TXT</strong> record at your DNS provider</li><li>Click <strong>Verify DNS</strong></li><li>Point the hostname (A/CNAME + TLS) at the same app that serves <code>go.elosync.com</code></li></ol><p>After verification, new short URLs prefer your custom domain.</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>Active</td><td>Redirects visitors to the destination URL</td></tr><tr><td>Paused</td><td>Redirect shows an EloSync-branded unavailable page; link remains editable</td></tr></tbody></table><p>Expired links (past <strong>Expires at</strong>) and deleted links also stop redirecting.</p><h2 id="public-redirects" tabindex="-1">Public redirects <a class="header-anchor" href="#public-redirects" aria-label="Permalink to &quot;Public redirects&quot;">​</a></h2><p>Visitors open the short URL without signing in. Clicks are recorded asynchronously (bots are redirected but not counted). UTM parameters configured on the link are appended to the destination URL on redirect.</p><p>When a link is missing, paused, expired, or deleted, visitors see an <strong>EloSync-branded page</strong> with links to learn about EloSync and join the Founding Beta — not a plain browser error page.</p>',24)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
